{
  "name": "RadExtract AI",
  "description": "A specialized research tool for extracting structured clinical variables from radiology reports and merging them with patient cohorts for analysis."
}

// types.ts

export enum AppStatus {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

// Represents a row from the initial patient list (Excel/CSV)
export interface PatientRecord {
  id: string; // Maps to Study ID or MRN
  name?: string;
  dob?: string;
  gender?: string;
  examDate?: string;
  // Dynamic fields for other columns in the initial extract
  [key: string]: string | number | boolean | undefined;
}

// Represents the data extracted from the Radiology Report
export interface ExtractedData {
  // Fractures
  rr_fractures: number; // 1=yes, 0=no
  rr_fractures_cspine: number;
  rr_fractures_calvarium: number;
  rr_fractures_skull_base: number;
  rr_fractures_leforte: number;
  rr_fractures_cricoid: number;
  rr_fractures_hyoid: number;
  rr_fractures_larynx: number;

  // Vascular
  rr_vascular_injury: number;
  rr_vessel_carotid: number;
  rr_vessel_vertebral: number;
  rr_vessel_internal_jugular: number;
  rr_vessel_other: number;
  rr_vessel_other_specify: string;
  rr_vessel_injured_report_comments: string;

  // Biffl Grading
  rr_biffl_grading_used: number;
  rr_biffl_grade: string;
  rr_reviewed_biffl_grade: string;

  // Brain Pathology
  rr_brain_pathology: number;
  rr_brain_pathology_details: number; // 1=ischemia, 2=hemorrhage
  rr_brain_pathology_report_comments: string;
}

// The combined object used for the final analysis sheet
export interface MergedRecord extends PatientRecord {
  radiologyReportText?: string;
  extractionStatus: 'PENDING' | 'EXTRACTED' | 'REVIEWED';
  extractedData?: ExtractedData;
}

// services/geminiService.ts
import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ExtractedData } from "../types";
import { EMPTY_EXTRACTION } from "../constants";

// Define the schema for the AI response to ensure strict JSON output matching our variables
const extractionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    rr_fractures: { type: Type.INTEGER, description: "1 if any fractures present, 0 if not" },
    rr_fractures_cspine: { type: Type.INTEGER, description: "1 if cervical spine fracture, 0 if not" },
    rr_fractures_calvarium: { type: Type.INTEGER, description: "1 if calvarium fracture, 0 if not" },
    rr_fractures_skull_base: { type: Type.INTEGER, description: "1 if skull base fracture, 0 if not" },
    rr_fractures_leforte: { type: Type.INTEGER, description: "1 if Le Fort fracture, 0 if not" },
    rr_fractures_cricoid: { type: Type.INTEGER, description: "1 if cricoid fracture, 0 if not" },
    rr_fractures_hyoid: { type: Type.INTEGER, description: "1 if hyoid fracture, 0 if not" },
    rr_fractures_larynx: { type: Type.INTEGER, description: "1 if larynx fracture, 0 if not" },

    rr_vascular_injury: { type: Type.INTEGER, description: "1 if any vascular injury, 0 if not" },
    rr_vessel_carotid: { type: Type.INTEGER, description: "1 if carotid artery injury, 0 if not" },
    rr_vessel_vertebral: { type: Type.INTEGER, description: "1 if vertebral artery injury, 0 if not" },
    rr_vessel_internal_jugular: { type: Type.INTEGER, description: "1 if internal jugular vein injury, 0 if not" },
    rr_vessel_other: { type: Type.INTEGER, description: "1 if other vessel injury, 0 if not" },
    rr_vessel_other_specify: { type: Type.STRING, description: "Name of other vessel injured, empty if none" },
    rr_vessel_injured_report_comments: { type: Type.STRING, description: "Brief summary of vascular findings" },

    rr_biffl_grading_used: { type: Type.INTEGER, description: "1 if Biffl grading mentioned, 0 if not" },
    rr_biffl_grade: { type: Type.STRING, description: "The Biffl grade (e.g., '1', '2', 'IV'), empty if none" },

    rr_brain_pathology: { type: Type.INTEGER, description: "1 if brain pathology present, 0 if not" },
    rr_brain_pathology_details: { type: Type.INTEGER, description: "1 for ischemia/infarct, 2 for hemorrhage, 0 if neither/none" },
    rr_brain_pathology_report_comments: { type: Type.STRING, description: "Brief summary of brain pathology" },
  },
  required: [
    "rr_fractures", "rr_fractures_cspine", "rr_vascular_injury", "rr_brain_pathology"
  ]
};

export const extractDataFromReport = async (reportText: string): Promise<ExtractedData> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a specialized medical data extractor for a research project.
    Analyze the following Radiology Report text.
    Extract the specific variables defined in the schema.

    Rules:
    - Use 1 for Yes/Present and 0 for No/Absent.
    - Be precise. If a finding is "suspected" or "possible", treat it as 0 unless the conclusion confirms it.
    - For brain pathology details: Return 1 if ischemia/stroke, 2 if hemorrhage/bleed.
    - If specific grades aren't found, leave strings empty.

    Report Text:
    """
    ${reportText}
    """
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: extractionSchema,
        temperature: 0.1, // Low temperature for deterministic extraction
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const parsed = JSON.parse(text);

    // Merge with empty to ensure all keys exist even if AI omits optional ones
    return { ...EMPTY_EXTRACTION, ...parsed };

  } catch (error) {
    console.error("Extraction error:", error);
    throw error;
  }
};

// components/PatientUploader.tsx
import React, { useState } from 'react';
import { PatientRecord } from '../types';

interface Props {
  onDataLoaded: (data: PatientRecord[]) => void;
}

export const PatientUploader: React.FC<Props> = ({ onDataLoaded }) => {
  const [inputText, setInputText] = useState('');

  const handleProcess = () => {
    // Simple CSV parser for demonstration. 
    // In production, use PapaParse.
    const lines = inputText.trim().split('\n');
    if (lines.length < 2) return;

    const headers = lines[0].split(',').map(h => h.trim());
    const records: PatientRecord[] = lines.slice(1).map((line, idx) => {
      const values = line.split(',').map(v => v.trim());
      const record: PatientRecord = {
        id: values[0] || `Unknown-${idx}`, // Assume first col is ID
        name: values[1] || 'Unknown',
      };

      // Map rest dynamically
      headers.forEach((h, i) => {
        if (i > 1 && values[i]) {
          record[h] = values[i];
        }
      });
      return record;
    });

    onDataLoaded(records);
  };

  const loadSample = () => {
    const sample = `StudyID,Name,DOB,Gender,Mechanism
101,John Doe,1980-05-12,M,MVA
102,Jane Smith,1992-11-20,F,Fall from height
103,Bob Jones,1975-02-15,M,Assault`;
    setInputText(sample);
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-sm border border-slate-200">
      <h2 className="text-xl font-semibold text-slate-800 mb-4">Step 1: Import Patient Cohort</h2>
      <p className="text-sm text-slate-500 mb-4">
        Paste your CSV data here (header row required). The first column should be the Study ID/MRN.
      </p>

      <textarea
        className="w-full h-48 p-3 border border-slate-300 rounded-md font-mono text-sm focus:ring-2 focus:ring-indigo-500 focus:outline-none"
        placeholder="StudyID, Name, DOB, ..."
        value={inputText}
        onChange={(e) => setInputText(e.target.value)}
      />

      <div className="mt-4 flex gap-3">
        <button
          onClick={handleProcess}
          disabled={!inputText}
          className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 disabled:opacity-50 font-medium transition-colors"
        >
          Load Patients
        </button>
        <button
          onClick={loadSample}
          className="px-4 py-2 text-indigo-600 bg-indigo-50 rounded-md hover:bg-indigo-100 font-medium transition-colors"
        >
          Load Sample Data
        </button>
      </div>
    </div>
  );
};

// components/AnalysisView.tsx
import React, { useState, useEffect } from 'react';
import { MergedRecord, ExtractedData, AppStatus } from '../types';
import { extractDataFromReport } from '../services/geminiService';
import { Loader2, CheckCircle, AlertCircle, FileText, BrainCircuit } from 'lucide-react';

interface Props {
  patient: MergedRecord;
  onUpdate: (updatedPatient: MergedRecord) => void;
  onBack: () => void;
}

export const AnalysisView: React.FC<Props> = ({ patient, onUpdate, onBack }) => {
  const [reportText, setReportText] = useState(patient.radiologyReportText || '');
  const [data, setData] = useState<ExtractedData | undefined>(patient.extractedData);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState('');

  const handleExtract = async () => {
    if (!reportText.trim()) return;

    setStatus(AppStatus.LOADING);
    setErrorMsg('');

    try {
      const result = await extractDataFromReport(reportText);
      setData(result);
      setStatus(AppStatus.SUCCESS);

      // Auto-save loosely
      onUpdate({
        ...patient,
        radiologyReportText: reportText,
        extractedData: result,
        extractionStatus: 'REVIEWED' // Mark as reviewed immediately for flow, or 'EXTRACTED'
      });
    } catch (err) {
      console.error(err);
      setStatus(AppStatus.ERROR);
      setErrorMsg("Failed to extract data. Check API key and try again.");
    }
  };

  const handleFieldChange = (key: keyof ExtractedData, value: any) => {
    if (!data) return;
    const newData = { ...data, [key]: value };
    setData(newData);
    onUpdate({
      ...patient,
      radiologyReportText: reportText,
      extractedData: newData,
      extractionStatus: 'REVIEWED'
    });
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)]">
      {/* Header */}
      <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-200">
        <div>
          <button onClick={onBack} className="text-sm text-slate-500 hover:text-indigo-600 mb-1">
            ← Back to List
          </button>
          <h2 className="text-2xl font-bold text-slate-800">
            {patient.name} <span className="text-slate-400 font-normal">#{patient.id}</span>
          </h2>
        </div>
        <div className="flex gap-2">
            <span className={`px-3 py-1 rounded-full text-sm font-medium ${
                status === AppStatus.SUCCESS ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-600'
            }`}>
                {status === AppStatus.SUCCESS ? 'Extraction Complete' : 'Ready to Process'}
            </span>
        </div>
      </div>

      <div className="flex flex-1 gap-6 overflow-hidden">
        {/* Left: Report Input */}
        <div className="w-1/2 flex flex-col">
          <label className="block text-sm font-medium text-slate-700 mb-2 flex items-center gap-2">
            <FileText className="w-4 h-4" />
            Radiology Report Text
          </label>
          <div className="flex-1 relative">
            <textarea
              className="w-full h-full p-4 border border-slate-300 rounded-lg resize-none focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm leading-relaxed"
              placeholder="Paste the full text of the radiology report here..."
              value={reportText}
              onChange={(e) => setReportText(e.target.value)}
            />
            <button
              onClick={handleExtract}
              disabled={status === AppStatus.LOADING || !reportText}
              className="absolute bottom-4 right-4 bg-indigo-600 text-white px-4 py-2 rounded-md shadow-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 transition-all"
            >
              {status === AppStatus.LOADING ? (
                <><Loader2 className="w-4 h-4 animate-spin" /> Analyzing...</>
              ) : (
                <><BrainCircuit className="w-4 h-4" /> Extract Data</>
              )}
            </button>
          </div>
          {errorMsg && (
             <div className="mt-2 p-3 bg-red-50 text-red-700 rounded-md text-sm flex items-center gap-2">
                <AlertCircle className="w-4 h-4" /> {errorMsg}
             </div>
          )}
        </div>

        {/* Right: Extracted Data Form */}
        <div className="w-1/2 overflow-y-auto pr-2">
          <div className="bg-slate-50 p-6 rounded-lg border border-slate-200">
            <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
              <CheckCircle className="w-5 h-5 text-green-600" />
              Extracted Variables
            </h3>

            {!data ? (
              <div className="text-center py-12 text-slate-400">
                <p>Paste a report and click "Extract Data" to see results here.</p>
              </div>
            ) : (
              <div className="space-y-6">

                {/* Fractures Section */}
                <div className="space-y-3">
                  <h4 className="text-sm font-bold text-slate-900 uppercase tracking-wide border-b pb-1">Fractures</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <BooleanSelect label="Fractures (Any)" value={data.rr_fractures} onChange={(v) => handleFieldChange('rr_fractures', v)} />
                    <BooleanSelect label="C-Spine" value={data.rr_fractures_cspine} onChange={(v) => handleFieldChange('rr_fractures_cspine', v)} />
                    <BooleanSelect label="Calvarium" value={data.rr_fractures_calvarium} onChange={(v) => handleFieldChange('rr_fractures_calvarium', v)} />
                    <BooleanSelect label="Skull Base" value={data.rr_fractures_skull_base} onChange={(v) => handleFieldChange('rr_fractures_skull_base', v)} />
                    <BooleanSelect label="Le Fort" value={data.rr_fractures_leforte} onChange={(v) => handleFieldChange('rr_fractures_leforte', v)} />
                    <BooleanSelect label="Larynx" value={data.rr_fractures_larynx} onChange={(v) => handleFieldChange('rr_fractures_larynx', v)} />
                  </div>
                </div>

                {/* Vascular Section */}
                <div className="space-y-3">
                  <h4 className="text-sm font-bold text-slate-900 uppercase tracking-wide border-b pb-1">Vascular Injury</h4>
                  <div className="grid grid-cols-2 gap-4">
                    <BooleanSelect label="Vascular Injury (Any)" value={data.rr_vascular_injury} onChange={(v) => handleFieldChange('rr_vascular_injury', v)} />
                    <BooleanSelect label="Carotid" value={data.rr_vessel_carotid} onChange={(v) => handleFieldChange('rr_vessel_carotid', v)} />
                    <BooleanSelect label="Vertebral" value={data.rr_vessel_vertebral} onChange={(v) => handleFieldChange('rr_vessel_vertebral', v)} />
                    <BooleanSelect label="Internal Jugular" value={data.rr_vessel_internal_jugular} onChange={(v) => handleFieldChange('rr_vessel_internal_jugular', v)} />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">Vascular Comments</label>
                    <input 
                        type="text" 
                        className="w-full p-2 border border-slate-300 rounded text-sm"
                        value={data.rr_vessel_injured_report_comments}
                        onChange={(e) => handleFieldChange('rr_vessel_injured_report_comments', e.target.value)}
                    />
                  </div>
                </div>

                {/* Biffl Grade */}
                <div className="space-y-3">
                    <h4 className="text-sm font-bold text-slate-900 uppercase tracking-wide border-b pb-1">Grading</h4>
                    <div className="grid grid-cols-2 gap-4">
                         <BooleanSelect label="Biffl Grading Used" value={data.rr_biffl_grading_used} onChange={(v) => handleFieldChange('rr_biffl_grading_used', v)} />
                         <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">Biffl Grade</label>
                            <input 
                                type="text" 
                                className="w-full p-2 border border-slate-300 rounded text-sm"
                                value={data.rr_biffl_grade}
                                onChange={(e) => handleFieldChange('rr_biffl_grade', e.target.value)}
                            />
                        </div>
                    </div>
                </div>

                 {/* Brain Pathology */}
                 <div className="space-y-3">
                    <h4 className="text-sm font-bold text-slate-900 uppercase tracking-wide border-b pb-1">Brain Pathology</h4>
                    <div className="grid grid-cols-2 gap-4">
                         <BooleanSelect label="Pathology Present" value={data.rr_brain_pathology} onChange={(v) => handleFieldChange('rr_brain_pathology', v)} />
                         <div>
                            <label className="block text-xs font-medium text-slate-500 mb-1">Details (1=Isch, 2=Hem)</label>
                            <select 
                                className="w-full p-2 border border-slate-300 rounded text-sm bg-white"
                                value={data.rr_brain_pathology_details}
                                onChange={(e) => handleFieldChange('rr_brain_pathology_details', parseInt(e.target.value))}
                            >
                                <option value={0}>None</option>
                                <option value={1}>Ischemia (1)</option>
                                <option value={2}>Hemorrhage (2)</option>
                            </select>
                        </div>
                    </div>
                    <div>
                    <label className="block text-xs font-medium text-slate-500 mb-1">Brain Comments</label>
                    <input 
                        type="text" 
                        className="w-full p-2 border border-slate-300 rounded text-sm"
                        value={data.rr_brain_pathology_report_comments}
                        onChange={(e) => handleFieldChange('rr_brain_pathology_report_comments', e.target.value)}
                    />
                  </div>
                </div>

              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

// Helper sub-component for boolean 0/1 selection
const BooleanSelect: React.FC<{ label: string, value: number, onChange: (v: number) => void }> = ({ label, value, onChange }) => (
    <div>
        <label className="block text-xs font-medium text-slate-500 mb-1">{label}</label>
        <div className="flex bg-white rounded-md border border-slate-300 overflow-hidden">
            <button 
                className={`flex-1 py-1 text-xs font-medium ${value === 1 ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:bg-slate-50'}`}
                onClick={() => onChange(1)}
            >
                Yes (1)
            </button>
            <div className="w-px bg-slate-300"></div>
            <button 
                className={`flex-1 py-1 text-xs font-medium ${value === 0 ? 'bg-slate-200 text-slate-800 shadow-inner' : 'text-slate-600 hover:bg-slate-50'}`}
                onClick={() => onChange(0)}
            >
                No (0)
            </button>
        </div>
    </div>
);

// components/MasterTable.tsx
import React from 'react';
import { MergedRecord } from '../types';
import { Edit2, CheckCircle, Clock, AlertCircle, Download } from 'lucide-react';

interface Props {
  data: MergedRecord[];
  onSelect: (id: string) => void;
  onExport: () => void;
}

export const MasterTable: React.FC<Props> = ({ data, onSelect, onExport }) => {

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'REVIEWED': return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'EXTRACTED': return <AlertCircle className="w-4 h-4 text-amber-500" />;
      default: return <Clock className="w-4 h-4 text-slate-300" />;
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col h-full">
      <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50 rounded-t-lg">
        <div>
            <h2 className="text-lg font-semibold text-slate-800">Patient Data Sheet</h2>
            <p className="text-xs text-slate-500">
                {data.length} records • {data.filter(d => d.extractionStatus === 'REVIEWED').length} completed
            </p>
        </div>
        <button 
            onClick={onExport}
            className="flex items-center gap-2 bg-white border border-slate-300 text-slate-700 px-3 py-1.5 rounded-md text-sm font-medium hover:bg-slate-50 transition-colors"
        >
            <Download className="w-4 h-4" /> Export CSV
        </button>
      </div>

      <div className="overflow-auto flex-1">
        <table className="w-full text-left text-sm text-slate-600">
          <thead className="bg-slate-100 sticky top-0 z-10 text-xs uppercase font-semibold text-slate-500">
            <tr>
              <th className="px-4 py-3 border-b">Status</th>
              <th className="px-4 py-3 border-b">Study ID</th>
              <th className="px-4 py-3 border-b">Patient Name</th>
              <th className="px-4 py-3 border-b text-center">Fracture?</th>
              <th className="px-4 py-3 border-b text-center">Vascular?</th>
              <th className="px-4 py-3 border-b text-center">Brain Path?</th>
              <th className="px-4 py-3 border-b text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {data.map((row) => (
              <tr key={row.id} className="hover:bg-indigo-50 transition-colors">
                <td className="px-4 py-3">
                  <div className="flex items-center gap-2" title={row.extractionStatus}>
                    {getStatusIcon(row.extractionStatus)}
                  </div>
                </td>
                <td className="px-4 py-3 font-medium text-slate-900">{row.id}</td>
                <td className="px-4 py-3">{row.name || '-'}</td>

                {/* Quick stats columns */}
                <td className="px-4 py-3 text-center">
                    {row.extractedData?.rr_fractures === 1 ? 
                        <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded text-xs font-bold">YES</span> : 
                        <span className="text-slate-300">-</span>
                    }
                </td>
                <td className="px-4 py-3 text-center">
                    {row.extractedData?.rr_vascular_injury === 1 ? 
                        <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded text-xs font-bold">YES</span> : 
                        <span className="text-slate-300">-</span>
                    }
                </td>
                 <td className="px-4 py-3 text-center">
                    {row.extractedData?.rr_brain_pathology === 1 ? 
                        <span className="bg-red-100 text-red-700 px-2 py-0.5 rounded text-xs font-bold">YES</span> : 
                        <span className="text-slate-300">-</span>
                    }
                </td>

                <td className="px-4 py-3 text-right">
                  <button
                    onClick={() => onSelect(row.id)}
                    className="text-indigo-600 hover:text-indigo-800 font-medium inline-flex items-center gap-1"
                  >
                    <Edit2 className="w-3 h-3" /> {row.extractionStatus === 'PENDING' ? 'Process' : 'Edit'}
                  </button>
                </td>
              </tr>
            ))}
            {data.length === 0 && (
                <tr>
                    <td colSpan={7} className="text-center py-12 text-slate-400">
                        No patients loaded yet. Start by uploading the initial extract.
                    </td>
                </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

// App.tsx
import React, { useState } from 'react';
import { PatientRecord, MergedRecord, ExtractedData } from './types';
import { PatientUploader } from './components/PatientUploader';
import { MasterTable } from './components/MasterTable';
import { AnalysisView } from './components/AnalysisView';
import { Stethoscope, Database, FileSpreadsheet } from 'lucide-react';

const App: React.FC = () => {
  // State
  const [patientData, setPatientData] = useState<MergedRecord[]>([]);
  const [selectedPatientId, setSelectedPatientId] = useState<string | null>(null);
  const [view, setView] = useState<'UPLOAD' | 'LIST' | 'DETAIL'>('UPLOAD');

  // Load initial CSV
  const handleDataLoaded = (records: PatientRecord[]) => {
    const merged: MergedRecord[] = records.map(r => ({
      ...r,
      extractionStatus: 'PENDING'
    }));
    setPatientData(merged);
    setView('LIST');
  };

  // Select a patient for analysis
  const handleSelectPatient = (id: string) => {
    setSelectedPatientId(id);
    setView('DETAIL');
  };

  // Update a single patient record (after AI extraction or manual edit)
  const handleUpdatePatient = (updated: MergedRecord) => {
    setPatientData(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  // Export Logic
  const handleExport = () => {
    if (patientData.length === 0) return;

    // 1. Collect all headers (Patient info + Extracted Data keys)
    const patientKeys = Object.keys(patientData[0]).filter(k => k !== 'extractedData' && k !== 'radiologyReportText' && k !== 'extractionStatus');
    // We use a sample extracted object to get keys, or predefined keys
    const extractedKeys = [
        "rr_fractures", "rr_fractures_cspine", "rr_fractures_calvarium", "rr_fractures_skull_base",
        "rr_fractures_leforte", "rr_fractures_cricoid", "rr_fractures_hyoid", "rr_fractures_larynx",
        "rr_vascular_injury", "rr_vessel_carotid", "rr_vessel_vertebral", "rr_vessel_internal_jugular",
        "rr_vessel_other", "rr_vessel_other_specify", "rr_vessel_injured_report_comments",
        "rr_biffl_grading_used", "rr_biffl_grade", "rr_reviewed_biffl_grade",
        "rr_brain_pathology", "rr_brain_pathology_details", "rr_brain_pathology_report_comments"
    ];

    const headerRow = [...patientKeys, ...extractedKeys].join(',');

    // 2. Build rows
    const rows = patientData.map(p => {
        const pValues = patientKeys.map(k => `"${p[k] || ''}"`);
        const eData = p.extractedData as any || {};
        const eValues = extractedKeys.map(k => `"${eData[k] !== undefined ? eData[k] : ''}"`);
        return [...pValues, ...eValues].join(',');
    });

    const csvContent = [headerRow, ...rows].join('\n');

    // 3. Download
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'final_master_sheet.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900 flex flex-col">
      {/* Top Navigation */}
      <header className="bg-indigo-900 text-white shadow-md">
        <div className="container mx-auto px-4 h-16 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="bg-white/10 p-2 rounded-lg">
                    <Stethoscope className="w-6 h-6 text-indigo-300" />
                </div>
                <div>
                    <h1 className="text-xl font-bold tracking-tight">RadExtract <span className="text-indigo-300 font-normal">AI</span></h1>
                    <p className="text-xs text-indigo-200">Radiology Report Variable Extractor</p>
                </div>
            </div>

            {patientData.length > 0 && (
                <div className="flex gap-4 text-sm">
                    <button 
                        onClick={() => setView('LIST')}
                        className={`flex items-center gap-2 px-3 py-1 rounded transition-colors ${view === 'LIST' ? 'bg-white/20' : 'hover:bg-white/10'}`}
                    >
                        <Database className="w-4 h-4" /> Data Sheet
                    </button>
                     <button 
                        onClick={() => setView('UPLOAD')}
                        className={`flex items-center gap-2 px-3 py-1 rounded transition-colors ${view === 'UPLOAD' ? 'bg-white/20' : 'hover:bg-white/10'}`}
                    >
                        <FileSpreadsheet className="w-4 h-4" /> Import New
                    </button>
                </div>
            )}
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 py-6 overflow-hidden">
        {view === 'UPLOAD' && (
            <div className="max-w-2xl mx-auto mt-10">
                <PatientUploader onDataLoaded={handleDataLoaded} />
                {patientData.length > 0 && (
                    <div className="text-center mt-6">
                        <button onClick={() => setView('LIST')} className="text-indigo-600 hover:underline">
                            Cancel and return to list
                        </button>
                    </div>
                )}
            </div>
        )}

        {view === 'LIST' && (
            <div className="h-[calc(100vh-140px)]">
                <MasterTable 
                    data={patientData} 
                    onSelect={handleSelectPatient} 
                    onExport={handleExport}
                />
            </div>
        )}

        {view === 'DETAIL' && selectedPatientId && (
            <AnalysisView 
                patient={patientData.find(p => p.id === selectedPatientId)!}
                onUpdate={handleUpdatePatient}
                onBack={() => setView('LIST')}
            />
        )}
      </main>
    </div>
  );
};

