// components/PatientUploader.tsx
import React, { useState, useRef } from 'react';
import { PatientRecord } from '../types';
import { Upload, FileText, AlertCircle } from 'lucide-react';
import * as XLSX from 'xlsx';

interface Props {
  onDataLoaded: (data: PatientRecord[]) => void;
}

export const PatientUploader: React.FC<Props> = ({ onDataLoaded }) => {
  const [inputText, setInputText] = useState('');
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Common processor for data from File (Excel/CSV) or Text Area
  const processRawData = (rows: any[][]) => {
    if (rows.length < 2) {
        setError("File appears empty or missing header row.");
        return;
    }

    // Row 0 is assumed to be headers
    const headers = rows[0].map((h: any) => String(h).trim());

    const records: PatientRecord[] = rows.slice(1).map((row, idx) => {
      const record: PatientRecord = {
        id: `Unknown-${idx}`,
        name: 'Unknown'
      };

      headers.forEach((h: string, i: number) => {
        if (row[i] !== undefined && row[i] !== null) {
            const val = row[i];
            const headerLower = h.toLowerCase();

            // Smart mapping for common ID/Name columns
            if (headerLower === 'id' || headerLower === 'study id' || headerLower === 'mrn' || headerLower === 'studyid') {
                record.id = String(val);
            } else if (headerLower.includes('name') && !headerLower.includes('file')) {
                record.name = String(val);
            } else {
                // Keep all other columns dynamically
                record[h] = val; 
            }
        }
      });

      // Fallback: If ID wasn't found in a column named "id", assume first column is ID
      if (record.id.startsWith('Unknown-') && row[0]) {
          record.id = String(row[0]);
      }

      return record;
    });

    onDataLoaded(records);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    setError(null);
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
        try {
            const data = evt.target?.result;
            // Read the file buffer
            const workbook = XLSX.read(data, { type: 'array' });
            // Get first sheet
            const firstSheetName = workbook.SheetNames[0];
            const worksheet = workbook.Sheets[firstSheetName];
            // Convert to JSON array of arrays (header: 1)
            const json = XLSX.utils.sheet_to_json(worksheet, { header: 1 }) as any[][];
            processRawData(json);
        } catch (err) {
            console.error(err);
            setError("Failed to parse file. Please ensure it is a valid Excel or CSV file.");
        }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleManualProcess = () => {
    setError(null);
    if (!inputText.trim()) return;

    // Simple CSV parser for manual text area
    // Handles basic commas, does not handle quoted commas well (use file upload for that)
    const lines = inputText.trim().split('\n');
    const rows = lines.map(line => line.split(',').map(c => c.trim()));
    processRawData(rows);
  };

  const loadSample = () => {
    const sample = `StudyID,Name,DOB,Gender,Mechanism
101,John Doe,1980-05-12,M,MVA
102,Jane Smith,1992-11-20,F,Fall from height
103,Bob Jones,1975-02-15,M,Assault`;
    setInputText(sample);
  };

  return (
    <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200">
      <h2 className="text-2xl font-bold text-slate-800 mb-2">Import Patient Cohort</h2>
      <p className="text-slate-500 mb-8">
        Upload an Excel or CSV file to begin. The first row must be headers (e.g., Study ID, Name).
      </p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

        {/* Option 1: File Upload */}
        <div className="border-2 border-dashed border-slate-300 rounded-lg p-8 flex flex-col items-center justify-center text-center hover:bg-slate-50 transition-colors group cursor-pointer"
             onClick={() => fileInputRef.current?.click()}>
            <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mb-4 group-hover:bg-indigo-100 transition-colors">
                <Upload className="w-8 h-8" />
            </div>
            <h3 className="font-semibold text-slate-900 mb-1">Upload File</h3>
            <p className="text-sm text-slate-500 mb-4">.xlsx, .xls, .csv</p>
            <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel"
                onChange={handleFileUpload}
            />
            <button className="px-4 py-2 bg-white border border-slate-300 text-slate-700 text-sm font-medium rounded-md shadow-sm group-hover:border-indigo-300 pointer-events-none">
                Select Spreadsheet
            </button>
        </div>

        {/* Option 2: Paste Text */}
        <div className="flex flex-col h-full">
            <div className="flex items-center justify-between mb-2">
                <label className="text-sm font-medium text-slate-700 flex items-center gap-2">
                    <FileText className="w-4 h-4" /> Or Paste CSV Data
                </label>
                <button onClick={loadSample} className="text-xs text-indigo-600 hover:text-indigo-800 font-medium">
                    Load Sample
                </button>
            </div>
            <textarea
                className="flex-1 w-full p-3 border border-slate-300 rounded-lg font-mono text-xs focus:ring-2 focus:ring-indigo-500 focus:outline-none resize-none mb-4"
                placeholder={`StudyID, Name, DOB...\n101, John Doe, ...`}
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
            />
            <button
                onClick={handleManualProcess}
                disabled={!inputText}
                className="w-full px-4 py-2 bg-slate-800 text-white rounded-md hover:bg-slate-900 disabled:opacity-50 font-medium transition-colors"
            >
                Process Text
            </button>
        </div>
      </div>

      {error && (
        <div className="mt-6 p-4 bg-red-50 text-red-700 rounded-lg flex items-center gap-2 text-sm">
            <AlertCircle className="w-5 h-5 flex-shrink-0" />
            {error}
        </div>
      )}
    </div>
  );
};

// types.ts

export enum AppStatus {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

// Represents a row from the initial patient list (Excel/CSV)
export interface PatientRecord {
  id: string; // Maps to Study ID or MRN
  name?: string;
  dob?: string;
  gender?: string;
  examDate?: string;
  // Dynamic fields for other columns in the initial extract
  [key: string]: any;
}

// Represents the data extracted from the Radiology Report
// Standard for Boolean-like fields: 0=No, 1=Yes, 2=N/A (Not Applicable)
export interface ExtractedData {
  // New Variable
  injury_mechanism: number; // 1=Strangulation, 2=Hanging, 0=Other/Unknown, 3=N/A

  // Fractures
  fractures: number; 
  fractures_cspine: number;
  fractures_calvarium: number;
  fractures_skull_base: number;
  fractures_leforte: number;
  fractures_cricoid: number;
  fractures_hyoid: number;
  fractures_larynx: number;

  // Vascular
  vascular_injury: number;
  vessel_carotid: number;
  vessel_vertebral: number;
  vessel_internal_jugular: number;
  vessel_other: number; // 0=No, 1=Yes, 2=N/A
  vessel_other_specify: string;
  vascular_report_comments: string;

  // Biffl Grading
  biffl_grading_used: number;
  biffl_grade: string;
  reviewed_biffl_grade: string;

  // Brain Pathology
  brain_pathology: number;
  brain_pathology_details: number; // 0=None, 1=Ischemia, 2=Hemorrhage, 3=N/A
  brain_pathology_comments: string;

  // Clinical History & Status
  ipv_history: number; // Intimate partner violence history
  gcs: string; // Glasgow Coma Scale
  intubated: number; 

  // Clinical Findings (Prefixes removed)
  soft_tissue_injury: number;
  loc: number; // Loss of Consciousness
  neuro_impaired: number;
  seizures: number;
  neck_pain: number;
  dysphagia: number;
  bruising: number;
  ligature: number;
  swelling: number;
  subconj_hemorrhages: number;
  c_spine_tenderness: number;
}

// The combined object used for the final analysis sheet
export interface MergedRecord extends PatientRecord {
  radiologyReportText?: string;
  extractionStatus: 'PENDING' | 'EXTRACTED' | 'REVIEWED';
  extractedData?: ExtractedData;
}

