// components/MasterTable.tsx
import React from 'react';
import { MergedRecord } from '../types';
import { Edit2, CheckCircle, Clock, AlertCircle, Download } from 'lucide-react';

interface Props {
  data: MergedRecord[];
  onSelect: (id: string) => void;
  onExport: () => void;
}

export const MasterTable: React.FC<Props> = ({ data, onSelect, onExport }) => {

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'REVIEWED': return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'EXTRACTED': return <AlertCircle className="w-4 h-4 text-amber-500" />;
      default: return <Clock className="w-4 h-4 text-slate-300" />;
    }
  };

  // Render raw codes 1, 0, 9 for data sheet clarity
  const renderStatus = (val: number | undefined) => {
    if (val === 1) return <span className="bg-green-100 text-green-700 border border-green-200 px-2 py-0.5 rounded text-xs font-mono font-bold">1</span>;
    if (val === 0) return <span className="bg-slate-100 text-slate-500 border border-slate-200 px-2 py-0.5 rounded text-xs font-mono">0</span>;
    if (val === 9) return <span className="text-slate-300 font-mono text-xs">9</span>;
    return <span className="text-slate-200">-</span>;
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col h-full">
      <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50 rounded-t-lg">
        <div>
            <h2 className="text-lg font-semibold text-slate-800">Patient Data Sheet</h2>
            <p className="text-xs text-slate-500">
                {data.length} records • {data.filter(d => d.extractionStatus === 'REVIEWED').length} completed
            </p>
        </div>
        <button 
            onClick={onExport}
            className="flex items-center gap-2 bg-white border border-slate-300 text-slate-700 px-3 py-1.5 rounded-md text-sm font-medium hover:bg-slate-50 transition-colors"
        >
            <Download className="w-4 h-4" /> Export CSV
        </button>
      </div>

      <div className="overflow-auto flex-1">
        <table className="w-full text-left text-sm text-slate-600">
          <thead className="bg-slate-100 sticky top-0 z-10 text-xs uppercase font-semibold text-slate-500">
            <tr>
              <th className="px-4 py-3 border-b">Status</th>
              <th className="px-4 py-3 border-b">Study ID</th>
              <th className="px-4 py-3 border-b">Patient Name</th>
              <th className="px-4 py-3 border-b">Age</th>
              <th className="px-4 py-3 border-b">Time to Study</th>
              <th className="px-4 py-3 border-b text-center">Fracture?</th>
              <th className="px-4 py-3 border-b text-center">Vascular?</th>
              <th className="px-4 py-3 border-b text-center">Brain Path?</th>
              <th className="px-4 py-3 border-b text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {data.map((row) => (
              <tr key={row.id} className="hover:bg-indigo-50 transition-colors">
                <td className="px-4 py-3">
                  <div className="flex items-center gap-2" title={row.extractionStatus}>
                    {getStatusIcon(row.extractionStatus)}
                  </div>
                </td>
                <td className="px-4 py-3 font-medium text-slate-900">{row.id}</td>
                <td className="px-4 py-3">{row.name || '-'}</td>
                <td className="px-4 py-3">{row.age || '-'}</td>
                <td className="px-4 py-3 font-mono text-xs">{row.timeToStudy || '-'}</td>

                {/* Quick stats columns using renamed variables */}
                <td className="px-4 py-3 text-center">
                    {renderStatus(row.extractedData?.fractures)}
                </td>
                <td className="px-4 py-3 text-center">
                    {renderStatus(row.extractedData?.vascular_injury)}
                </td>
                 <td className="px-4 py-3 text-center">
                    {renderStatus(row.extractedData?.brain_pathology)}
                </td>

                <td className="px-4 py-3 text-right">
                  <button
                    onClick={() => onSelect(row.id)}
                    className="text-indigo-600 hover:text-indigo-800 font-medium inline-flex items-center gap-1"
                  >
                    <Edit2 className="w-3 h-3" /> {row.extractionStatus === 'PENDING' ? 'Process' : 'Edit'}
                  </button>
                </td>
              </tr>
            ))}
            {data.length === 0 && (
                <tr>
                    <td colSpan={9} className="text-center py-12 text-slate-400">
                        No patients loaded yet. Start by uploading the initial extract.
                    </td>
                </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

// types.ts

export enum AppStatus {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

// Represents a row from the initial patient list (Excel/CSV)
export interface PatientRecord {
  id: string; // Maps to Study ID or MRN
  name?: string;
  dob?: string;
  gender?: string;
  examDate?: string; // Maps to Done Stamp
  createdDate?: string; // Maps to Created Stamp
  age?: number | string; // Calculated field
  timeToStudy?: string; // Calculated field (Done - Created)
  // Dynamic fields for other columns in the initial extract
  [key: string]: any;
}

// Represents the data extracted from the Radiology Report
// Standard for Boolean-like fields: 0=No, 1=Yes, 9=N/A (Not Applicable)
export interface ExtractedData {
  // New Variable
  injury_mechanism: number; // 1=Strangulation, 2=Hanging, 0=Other/Unknown, 9=N/A

  // Fractures
  fractures: number; // 9=N/A
  fractures_cspine: number;
  fractures_calvarium: number;
  fractures_skull_base: number;
  fractures_leforte: number;
  fractures_cricoid: number;
  fractures_hyoid: number;
  fractures_larynx: number;

  // Vascular
  vascular_injury: number;
  vessel_carotid: number;
  vessel_vertebral: number;
  vessel_internal_jugular: number;
  vessel_other: number; // 0=No, 1=Yes, 9=N/A
  vessel_other_specify: string;
  vascular_report_comments: string;

  // Biffl Grading
  biffl_grading_used: number; // 9=N/A
  biffl_grade: string;
  biffl_grade_comments: string;
  reviewed_biffl_grade: string;

  // Brain Pathology
  brain_pathology: number; // 9=N/A
  brain_pathology_details: number; // 0=None, 1=Ischemia, 2=Hemorrhage, 9=N/A
  brain_pathology_comments: string;

  // Clinical History & Status
  ipv_history: number; // Intimate partner violence history, 9=N/A
  gcs: string; // Glasgow Coma Scale
  intubated: number; // 9=N/A

  // Clinical Findings (Prefixes removed)
  soft_tissue_injury: number;
  loc: number; // Loss of Consciousness
  neuro_impaired: number;
  seizures: number;
  neck_pain: number;
  dysphagia: number;
  hoarseness: number;
  bruising: number;
  ligature: number;
  swelling: number;
  subconj_hemorrhages: number;
  c_spine_tenderness: number;
}

// The combined object used for the final analysis sheet
export interface MergedRecord extends PatientRecord {
  radiologyReportText?: string;
  extractionStatus: 'PENDING' | 'EXTRACTED' | 'REVIEWED';
  extractedData?: ExtractedData;
}

