import { GoogleGenAI, Type, Schema } from "@google/genai";
import { ExtractedData } from "../types";
import { EMPTY_EXTRACTION } from "../constants";

// Define the schema for the AI response to ensure strict JSON output matching our variables
const extractionSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    // New variable (Updated to use 9 for N/A)
    injury_mechanism: { type: Type.INTEGER, description: "1=Strangulation, 2=Hanging, 0=Other/Unknown, 9=N/A" },

    // Fractures
    fractures: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A" },
    fractures_cspine: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A" },
