  required: [
    "fractures", "fractures_cspine", "vascular_injury", "brain_pathology", 
    "ipv_history", "gcs", "intubated", "injury_mechanism"
  ]
};

export const extractDataFromReport = async (reportText: string): Promise<ExtractedData> => {
  // Debug check: This ensures the env var is actually loaded
  if (!process.env.API_KEY || process.env.API_KEY.includes("PASTE_YOUR_API_KEY")) {
    throw new Error("API Key is missing or invalid. Please check your .env file and restart the server.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a specialized medical data extractor for a research project.
    Analyze the following Radiology Report text.
    Extract the specific variables defined in the schema.

    Rules:
    - Use 1 for Yes/Present and 0 for No/Absent.
    - Use 9 for Not Applicable (N/A) if the finding is not mentioned, irrelevant to the study type, or explicitly stated as not applicable.
    - Be precise. If a finding is "suspected" or "possible", treat it as 0 (No) unless the conclusion confirms it.
    - For brain pathology details: Return 1 if ischemia/stroke, 2 if hemorrhage/bleed, 0 if neither/none, 9 if N/A.
    - For 'Other Vessel', if a vascular injury is present but not in the Carotid, Vertebral, or Internal Jugular, mark Other=1 and specify.
    - If specific grades aren't found, leave strings empty.
    - INJURY MECHANISM: Look for context about how the injury occurred. 
       - Code 1 = Strangulation (manual, chokehold, etc.)
       - Code 2 = Hanging
       - Code 0 = Other mechanism or Unknown.
    - Important: Also look at the 'Clinical History', 'Indication', or 'Reason for Exam' sections often found at the top of the report to extract clinical variables (e.g., GCS, Intubation, History of IPV, Signs of trauma like bruising/swelling, hoarseness).

    Report Text:
    """
    ${reportText}
    """
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: extractionSchema,
        temperature: 0.1, // Low temperature for deterministic extraction
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const parsed = JSON.parse(text);

    // Merge with empty to ensure all keys exist even if AI omits optional ones
    return { ...EMPTY_EXTRACTION, ...parsed };

  } catch (error) {
    console.error("Extraction error:", error);
    throw error;
  }
};

// components/AnalysisView.tsx
import React, { useState, useEffect } from 'react';
import { MergedRecord, ExtractedData, AppStatus } from '../types';
import { extractDataFromReport } from '../services/geminiService';
import { Loader2, CheckCircle, AlertCircle, FileText, BrainCircuit, Sparkles } from 'lucide-react';

interface Props {
  patient: MergedRecord;
  onUpdate: (updatedPatient: MergedRecord) => void;
  onBack: () => void;
}

export const AnalysisView: React.FC<Props> = ({ patient, onUpdate, onBack }) => {
  const [reportText, setReportText] = useState(patient.radiologyReportText || '');
  const [data, setData] = useState<ExtractedData | undefined>(patient.extractedData);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState('');

  // Allow passing specific text (e.g., from paste event) or use current state
  const handleExtract = async (textOverride?: string) => {
    const textToProcess = textOverride ?? reportText;

    if (!textToProcess || !textToProcess.trim()) {
        setErrorMsg("Please enter report text first.");
        return;
    }

    setStatus(AppStatus.LOADING);
    setErrorMsg('');

    try {
      const result = await extractDataFromReport(textToProcess);
      setData(result);
      setStatus(AppStatus.SUCCESS);

      // Save results
      onUpdate({
        ...patient,
        radiologyReportText: textToProcess,
        extractedData: result,
        extractionStatus: 'REVIEWED'
      });
    } catch (err: any) {
      console.error(err);
      setStatus(AppStatus.ERROR);

      // Robust error message extraction
      let msg = "Failed to extract data. Check API key and try again.";
      if (err instanceof Error) {
        msg = err.message;
      } else if (typeof err === 'string') {
        msg = err;
      } else if (err && typeof err === 'object') {
        // Try to stringify if it's an object (like a raw API response error)
        try {
            msg = JSON.stringify(err);
            // If it's too long, truncate or just show specific fields if known, 
            // but for debugging, full JSON is helpful.
            if (msg === '{}') msg = "Unknown error occurred (empty object).";
        } catch (e) {
            msg = "Unknown error occurred.";
        }
      }

      setErrorMsg(msg);
    }
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    const pastedText = e.clipboardData.getData('text');
    // If the text area is mostly empty and we paste a significant amount of text,
    // we assume it's a new report and trigger extraction automatically.
    if (reportText.trim().length < 50 && pastedText.length > 50) {
        // Trigger extraction with the pasted text
        handleExtract(pastedText);
    }
  };

  const handleFieldChange = (key: keyof ExtractedData, value: any) => {
    if (!data) return;
    const newData = { ...data, [key]: value };
    setData(newData);
    onUpdate({
      ...patient,
      radiologyReportText: reportText,
      extractedData: newData,
      extractionStatus: 'REVIEWED'
    });
  };

