    fractures_leforte: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    fractures_cricoid: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
