    vessel_carotid: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    vessel_vertebral: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    vessel_internal_jugular: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    vessel_other: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    vessel_other_specify: { type: Type.STRING, description: "Name of other vessel injured, empty if none" },
    vascular_report_comments: { type: Type.STRING, description: "Brief summary of vascular findings" },

    // Grading
    biffl_grading_used: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    biffl_grade: { type: Type.STRING, description: "The Biffl grade (I, II, III, IV), empty if none" },
    biffl_grade_comments: { type: Type.STRING, description: "Comments specific to the Biffl grading or why it was applied" },

    // Brain
    brain_pathology: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    // Updated to use 9 for N/A, 999 for Missing
    brain_pathology_details: { type: Type.INTEGER, description: "1=Ischemia/Infarct, 2=Hemorrhage, 0=None, 9=N/A, 999=Missing" },
    brain_pathology_comments: { type: Type.STRING, description: "Brief summary of brain pathology" },

    // Clinical & History
    ipv_history: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    gcs: { type: Type.STRING, description: "Glasgow Coma Scale score if mentioned (e.g., '15', '3', '14T')" },
    intubated: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },

    // Clinical Findings (renamed)
    soft_tissue_injury: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    loc: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    neuro_impaired: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    seizures: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    neck_pain: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    dysphagia: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    hoarseness: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    bruising: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    ligature: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    swelling: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    subconj_hemorrhages: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
    c_spine_tenderness: { type: Type.INTEGER, description: "1=Yes, 0=No, 9=N/A, 999=Missing" },
  },
  required: [
    "fractures", "fractures_cspine", "vascular_injury", "brain_pathology", 
    "ipv_history", "gcs", "intubated", "injury_mechanism"
  ]
};

export const extractDataFromReport = async (reportText: string): Promise<ExtractedData> => {
  // Debug check: This ensures the env var is actually loaded
  if (!process.env.API_KEY || process.env.API_KEY.includes("PASTE_YOUR_API_KEY")) {
    throw new Error("API Key is missing or invalid. Please check your .env file and restart the server.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a specialized medical data extractor for a research project.
    Analyze the following Radiology Report text.
    Extract the specific variables defined in the schema.

    Rules:
    - Use 1 for Yes/Present and 0 for No/Absent.
    - Use 9 for Not Applicable (N/A) if the finding is explicitly stated as not applicable or irrelevant to this type of study.
    - Use 999 for Missing if the finding is not mentioned in the report and cannot be determined.
    - Be precise. If a finding is "suspected" or "possible", treat it as 0 (No) unless the conclusion confirms it.
    - For brain pathology details: Return 1 if ischemia/stroke, 2 if hemorrhage/bleed, 0 if neither/none, 9 if N/A, 999 if Missing.
    - For 'Other Vessel', if a vascular injury is present but not in the Carotid, Vertebral, or Internal Jugular, mark Other=1 and specify.
    - If specific grades aren't found, leave strings empty.
    - INJURY MECHANISM: Look for context about how the injury occurred. 
       - Code 1 = Strangulation (manual, chokehold, etc.)
       - Code 2 = Hanging
       - Code 0 = Other mechanism or Unknown.
       - Code 999 = Missing/Not mentioned.
    - Important: Also look at the 'Clinical History', 'Indication', or 'Reason for Exam' sections often found at the top of the report to extract clinical variables (e.g., GCS, Intubation, History of IPV, Signs of trauma like bruising/swelling, hoarseness).

    Report Text:
    """
    ${reportText}
    """
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: extractionSchema,
        temperature: 0.1, // Low temperature for deterministic extraction
      },
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const parsed = JSON.parse(text);

    // Merge with empty to ensure all keys exist even if AI omits optional ones
    return { ...EMPTY_EXTRACTION, ...parsed };

  } catch (error) {
    console.error("Extraction error:", error);
    throw error;
  }
};

// components/AnalysisView.tsx
import React, { useState, useEffect } from 'react';
import { MergedRecord, ExtractedData, AppStatus } from '../types';
import { extractDataFromReport } from '../services/geminiService';
import { Loader2, CheckCircle, AlertCircle, FileText, BrainCircuit, Sparkles } from 'lucide-react';

interface Props {
  patient: MergedRecord;
  onUpdate: (updatedPatient: MergedRecord) => void;
  onBack: () => void;
}

export const AnalysisView: React.FC<Props> = ({ patient, onUpdate, onBack }) => {
  const [reportText, setReportText] = useState(patient.radiologyReportText || '');
  const [data, setData] = useState<ExtractedData | undefined>(patient.extractedData);
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [errorMsg, setErrorMsg] = useState('');

  // Allow passing specific text (e.g., from paste event) or use current state
  const handleExtract = async (textOverride?: string) => {
    const textToProcess = textOverride ?? reportText;

    if (!textToProcess || !textToProcess.trim()) {
        setErrorMsg("Please enter report text first.");
        return;
    }

    setStatus(AppStatus.LOADING);
    setErrorMsg('');

    try {
      const result = await extractDataFromReport(textToProcess);
      setData(result);
      setStatus(AppStatus.SUCCESS);

      // Save results
      onUpdate({
        ...patient,
        radiologyReportText: textToProcess,
        extractedData: result,
        extractionStatus: 'REVIEWED'
      });
    } catch (err: any) {
      console.error(err);
      setStatus(AppStatus.ERROR);

      // Robust error message extraction
      let msg = "Failed to extract data. Check API key and try again.";
      if (err instanceof Error) {
        msg = err.message;
      } else if (typeof err === 'string') {
        msg = err;
      } else if (err && typeof err === 'object') {
        // Try to stringify if it's an object (like a raw API response error)
        try {
            msg = JSON.stringify(err);
            // If it's too long, truncate or just show specific fields if known, 
            // but for debugging, full JSON is helpful.
            if (msg === '{}') msg = "Unknown error occurred (empty object).";
        } catch (e) {
            msg = "Unknown error occurred.";
        }
      }

      setErrorMsg(msg);
    }
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    const pastedText = e.clipboardData.getData('text');
    // If the text area is mostly empty and we paste a significant amount of text,
    // we assume it's a new report and trigger extraction automatically.
    if (reportText.trim().length < 50 && pastedText.length > 50) {
        // Trigger extraction with the pasted text
        handleExtract(pastedText);
    }
  };

  const handleFieldChange = (key: keyof ExtractedData, value: any) => {
    if (!data) return;
    const newData = { ...data, [key]: value };
    setData(newData);
    onUpdate({
      ...patient,
      radiologyReportText: reportText,
      extractedData: newData,
      extractionStatus: 'REVIEWED'
    });
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)]">
      {/* Header */}
      <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-200">
        <div>
          <button onClick={onBack} className="text-sm text-slate-500 hover:text-indigo-600 mb-1">
            ← Back to List
          </button>
          <h2 className="text-2xl font-bold text-slate-800">
            {patient.name} <span className="text-slate-400 font-normal">#{patient.id}</span>
          </h2>
        </div>
        <div className="flex gap-2">
            <span className={`px-3 py-1 rounded-full text-sm font-medium flex items-center gap-2 ${
                status === AppStatus.SUCCESS ? 'bg-green-100 text-green-700' : 
                status === AppStatus.LOADING ? 'bg-indigo-100 text-indigo-700' :
                status === AppStatus.ERROR ? 'bg-red-100 text-red-700' :
                'bg-slate-100 text-slate-600'
            }`}>
                {status === AppStatus.LOADING && <Loader2 className="w-3 h-3 animate-spin" />}
                {status === AppStatus.SUCCESS && <CheckCircle className="w-3 h-3" />}
                {status === AppStatus.ERROR && <AlertCircle className="w-3 h-3" />}
                {status === AppStatus.SUCCESS ? 'Extraction Complete' : 
                 status === AppStatus.LOADING ? 'Analyzing Report...' : 
                 status === AppStatus.ERROR ? 'Error' :
                 'Ready to Process'}
            </span>
        </div>
      </div>

      <div className="flex flex-1 gap-6 overflow-hidden">
        {/* Left: Report Input */}
        <div className="w-1/2 flex flex-col">
          <label className="block text-sm font-medium text-slate-700 mb-2 flex items-center gap-2">
            <FileText className="w-4 h-4" />
            Radiology Report Text
          </label>
          <div className="flex-1 relative group">
            <textarea
              className="w-full h-full p-4 border border-slate-300 rounded-lg resize-none focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm leading-relaxed font-mono bg-slate-50 focus:bg-white transition-colors"
              placeholder="Paste the full text of the radiology report here. Data extraction will start automatically..."
              value={reportText}
              onChange={(e) => setReportText(e.target.value)}
              onPaste={handlePaste}
            />
            {status === AppStatus.IDLE && !reportText && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-40">
                    <div className="flex flex-col items-center text-slate-400">
                        <FileText className="w-12 h-12 mb-2" />
                        <span className="text-sm font-medium">Paste Report to Analyze</span>
                    </div>
                </div>
            )}

            <button
              onClick={() => handleExtract()}
              disabled={status === AppStatus.LOADING || !reportText}
              className="absolute bottom-4 right-4 bg-indigo-600 text-white px-4 py-2 rounded-md shadow-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 transition-all z-10"
            >
              {status === AppStatus.LOADING ? (
                <><Loader2 className="w-4 h-4 animate-spin" /> Analyzing...</>
              ) : (
                <><BrainCircuit className="w-4 h-4" /> {data ? 'Re-analyze' : 'Extract Data'}</>
              )}
            </button>
          </div>
          {errorMsg && (
             <div className="mt-2 p-3 bg-red-50 text-red-700 rounded-md text-sm flex items-start gap-2 border border-red-200 break-words overflow-y-auto max-h-32">
                <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" /> 
                <span>{errorMsg}</span>
             </div>
          )}
        </div>

        {/* Right: Extracted Data Form */}
        <div className="w-1/2 overflow-y-auto pr-2 scroll-smooth">
          <div className={`bg-white p-6 rounded-lg border transition-all ${status === AppStatus.LOADING ? 'border-indigo-200 shadow-indigo-100 shadow-lg' : 'border-slate-200'}`}>
            <h3 className="text-lg font-semibold text-slate-800 mb-4 flex items-center gap-2">
              {status === AppStatus.LOADING ? (
                 <Sparkles className="w-5 h-5 text-indigo-500 animate-pulse" />
              ) : (
                 <CheckCircle className="w-5 h-5 text-green-600" />
              )}
              Extracted Variables
            </h3>

            {!data && status !== AppStatus.LOADING && (
              <div className="text-center py-20 text-slate-400 border-2 border-dashed border-slate-100 rounded-lg">
                <BrainCircuit className="w-12 h-12 mx-auto mb-3 opacity-20" />
                <p>Paste a report to automatically populate these fields.</p>
              </div>
            )}

            {status === AppStatus.LOADING && !data && (
                <div className="space-y-4 animate-pulse">
                    <div className="h-4 bg-slate-100 rounded w-1/3 mb-6"></div>
                    <div className="grid grid-cols-2 gap-4">
                        <div className="h-10 bg-slate-100 rounded"></div>
                        <div className="h-10 bg-slate-100 rounded"></div>
                        <div className="h-10 bg-slate-100 rounded"></div>
                        <div className="h-10 bg-slate-100 rounded"></div>
                    </div>
                </div>
            )}

            {data && (
              <div className={`space-y-8 transition-opacity duration-500 ${status === AppStatus.LOADING ? 'opacity-50' : 'opacity-100'}`}>

                {/* Clinical Information Section */}
                <div className="space-y-3">
