  const handleDataLoaded = (records: PatientRecord[]) => {
    // Preserve existing extraction status if ID matches, otherwise new
    const merged: MergedRecord[] = records.map(r => {
        const existing = patientData.find(p => p.id === r.id);
        if (existing) {
             // If we are re-uploading, merge carefully. 
             // If the new record has text (from folder upload), use it.
             return {
                 ...existing,
                 ...r,
                 radiologyReportText: (r as MergedRecord).radiologyReportText || existing.radiologyReportText,
                 reportFilename: (r as MergedRecord).reportFilename || existing.reportFilename
             };
        }
        return {
            ...r,
            extractionStatus: 'PENDING'
        };
    });
    setPatientData(merged);
    setView('LIST');
  };

  // Select a patient for analysis
  const handleSelectPatient = (id: string) => {
    if (isBatchProcessing) return; // Disable selection during batch
    setSelectedPatientId(id);
    setView('DETAIL');
  };

  // Update a single patient record (after AI extraction or manual edit)
  const handleUpdatePatient = (updated: MergedRecord) => {
    setPatientData(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  // --- Batch Processing Logic ---
  const handleBatchProcess = async () => {
    if (isBatchProcessing) {
        setIsBatchProcessing(false); // Stop requested
