// types.ts

export enum AppStatus {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

// Represents a row from the initial patient list (Excel/CSV)
export interface PatientRecord {
  id: string; // Maps to Study ID or MRN
  name?: string;
  dob?: string;
  gender?: string;
  examDate?: string; // Maps to Done Stamp
  createdDate?: string; // Maps to Created Stamp
  age?: number | string; // Calculated field
  timeToStudy?: string; // Calculated field (Done - Created)
  // Dynamic fields for other columns in the initial extract
  [key: string]: any;
}

// Represents the data extracted from the Radiology Report
// Standard for Boolean-like fields: 0=No, 1=Yes, 9=N/A, 999=Missing
export interface ExtractedData {
  // New Variable
  injury_mechanism: number; // 1=Strangulation, 2=Hanging, 0=Other/Unknown, 9=N/A, 999=Missing

  // Fractures
  fractures: number; // 9=N/A, 999=Missing
  fractures_cspine: number;
  fractures_calvarium: number;
  fractures_skull_base: number;
  fractures_leforte: number;
  fractures_cricoid: number;
  fractures_hyoid: number;
  fractures_larynx: number;

  // Vascular
  vascular_injury: number;
  vessel_carotid: number;
  vessel_vertebral: number;
  vessel_internal_jugular: number;
  vessel_other: number; // 0=No, 1=Yes, 9=N/A, 999=Missing
  vessel_other_specify: string;
  vascular_report_comments: string;

  // Biffl Grading
  biffl_grading_used: number; // 9=N/A, 999=Missing
  biffl_grade: string;
  biffl_grade_comments: string;
  reviewed_biffl_grade: string;

  // Brain Pathology
  brain_pathology: number; // 9=N/A, 999=Missing
  brain_pathology_details: number; // 0=None, 1=Ischemia, 2=Hemorrhage, 9=N/A, 999=Missing
  brain_pathology_comments: string;

  // Clinical History & Status
  ipv_history: number; // 1=Yes, 0=No, 9=N/A, 999=Missing
  gcs: string; // Glasgow Coma Scale
  intubated: number; // 9=N/A, 999=Missing

  // Clinical Findings (Prefixes removed)
  soft_tissue_injury: number;
  loc: number; // Loss of Consciousness
  neuro_impaired: number;
  seizures: number;
  neck_pain: number;
  dysphagia: number;
  hoarseness: number;
  bruising: number;
  ligature: number;
  swelling: number;
  subconj_hemorrhages: number;
  c_spine_tenderness: number;
}

// The combined object used for the final analysis sheet
export interface MergedRecord extends PatientRecord {
  radiologyReportText?: string;
  reportFilename?: string;
  extractionStatus: 'PENDING' | 'EXTRACTED' | 'REVIEWED' | 'ERROR';
  extractionError?: string;
  extractedData?: ExtractedData;
}

// App.tsx
import React, { useState } from 'react';
import { PatientRecord, MergedRecord, ExtractedData } from './types';
import { PatientUploader } from './components/PatientUploader';
import { MasterTable } from './components/MasterTable';
import { AnalysisView } from './components/AnalysisView';
import { extractDataFromReport } from './services/geminiService';
import { Stethoscope, Database, FileSpreadsheet, PlayCircle, StopCircle, Loader2, FileText, RefreshCw } from 'lucide-react';

const App: React.FC = () => {
  // State
  const [patientData, setPatientData] = useState<MergedRecord[]>([]);
  const [selectedPatientId, setSelectedPatientId] = useState<string | null>(null);
  const [view, setView] = useState<'UPLOAD' | 'LIST' | 'DETAIL'>('UPLOAD');

  // Batch Processing State
  const [isBatchProcessing, setIsBatchProcessing] = useState(false);
  const [batchProgress, setBatchProgress] = useState({ current: 0, total: 0 });

  // Load initial CSV or updated data from Uploader
  // UPDATED: Now merges incoming data with existing data (Upsert logic)
  const handleDataLoaded = (incomingRecords: PatientRecord[]) => {
    setPatientData(prevData => {
        const nextData = [...prevData];
        let newCount = 0;

        incomingRecords.forEach(incoming => {
            const index = nextData.findIndex(p => p.id === incoming.id);

            if (index >= 0) {
                // UPDATE existing record
                // We preserve extracted data and status, but allow updating patient details 
                // and attaching new report text if provided in this batch.
                const existing = nextData[index];
                nextData[index] = {
                    ...existing,
                    ...incoming,
                    // Only overwrite report text if the new incoming record actually has it (e.g. from folder upload)
                    radiologyReportText: (incoming as MergedRecord).radiologyReportText || existing.radiologyReportText,
                    reportFilename: (incoming as MergedRecord).reportFilename || existing.reportFilename,
                    // Create date/Age might be updated from CSV, but we keep extraction results
                    extractedData: existing.extractedData,
                    extractionStatus: existing.extractionStatus,
                    extractionError: existing.extractionError
                };
            } else {
                // INSERT new record
                nextData.push({
                    ...incoming,
                    extractionStatus: 'PENDING'
                });
                newCount++;
            }
        });

        return nextData;
    });
    setView('LIST');
  };

  // Select a patient for analysis
  const handleSelectPatient = (id: string) => {
    if (isBatchProcessing) return; // Disable selection during batch
    setSelectedPatientId(id);
    setView('DETAIL');
  };

  // Update a single patient record (after AI extraction or manual edit)
  const handleUpdatePatient = (updated: MergedRecord) => {
    setPatientData(prev => prev.map(p => p.id === updated.id ? updated : p));
  };

  // --- Batch Processing Logic ---
  const handleBatchProcess = async () => {
    if (isBatchProcessing) {
        setIsBatchProcessing(false); // Stop requested
        return;
    }

    // Find all patients that have report text but haven't been extracted OR failed previously
    const queue = patientData.filter(p => 
        p.radiologyReportText && 
        (p.extractionStatus === 'PENDING' || p.extractionStatus === 'ERROR')
    );

    if (queue.length === 0) {
        alert("No pending or failed records with report text found. Upload reports first.");
        return;
    }

    setIsBatchProcessing(true);
    setBatchProgress({ current: 0, total: queue.length });

    for (let i = 0; i < queue.length; i++) {
        // If user navigated away or component unmounted, stop might be tricky without ref
        // checking !isBatchProcessing here won't work due to closure, so we just run the queue

        const patient = queue[i];

        try {
            // Call AI
            const result = await extractDataFromReport(patient.radiologyReportText!);

            // Update State on Success
            handleUpdatePatient({
                ...patient,
                extractedData: result,
                extractionStatus: 'REVIEWED', // or EXTRACTED
                extractionError: undefined // Clear error
            });

            // Small delay to prevent rate limiting issues with Gemini API
            await new Promise(resolve => setTimeout(resolve, 1000)); 

        } catch (err: any) {
            console.error(`Error processing ${patient.id}:`, err);
            const errorMessage = err instanceof Error ? err.message : String(err);

            // Update State on Error so user sees it in table
            handleUpdatePatient({
                ...patient,
                extractionStatus: 'ERROR',
                extractionError: errorMessage
            });
        }

        setBatchProgress(prev => ({ ...prev, current: i + 1 }));
    }

    setIsBatchProcessing(false);
  };

  // Export Logic
  const handleExport = () => {
    if (patientData.length === 0) return;

    // 1. Collect all headers (Patient info + Extracted Data keys)
    const patientKeys = Object.keys(patientData[0]).filter(k => k !== 'extractedData' && k !== 'radiologyReportText' && k !== 'extractionStatus' && k !== 'extractionError');

    const extractedKeys = [
        "injury_mechanism",
        "ipv_history", "gcs", "intubated", 
        "soft_tissue_injury", "loc", "neuro_impaired",
        "seizures", "neck_pain", "dysphagia", "hoarseness",
        "bruising", "ligature", "swelling",
        "subconj_hemorrhages", "c_spine_tenderness",

        "fractures", "fractures_cspine", "fractures_calvarium", "fractures_skull_base",
        "fractures_leforte", "fractures_cricoid", "fractures_hyoid", "fractures_larynx",

        "vascular_injury", "vessel_carotid", "vessel_vertebral", "vessel_internal_jugular",
        "vessel_other", "vessel_other_specify", "vascular_report_comments",

        "biffl_grading_used", "biffl_grade", "biffl_grade_comments", "reviewed_biffl_grade",
        "brain_pathology", "brain_pathology_details", "brain_pathology_comments"
    ];

    const headerRow = [...patientKeys, "Report_Filename", "Extraction_Error", ...extractedKeys].join(',');

    // 2. Build rows
    const rows = patientData.map(p => {
        const pValues = patientKeys.map(k => `"${p[k] || ''}"`);
        const eData = p.extractedData as any || {};
        const eValues = extractedKeys.map(k => `"${eData[k] !== undefined ? eData[k] : ''}"`);
        // Include error message in export so they can analyze failures
        return [...pValues, `"${p.reportFilename || ''}"`, `"${p.extractionError || ''}"`, ...eValues].join(',');
    });

    const csvContent = [headerRow, ...rows].join('\n');

    // 3. Download
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', 'final_master_sheet.csv');
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Calculate counts for UI
  const pendingCount = patientData.filter(p => p.radiologyReportText && p.extractionStatus === 'PENDING').length;
  const errorCount = patientData.filter(p => p.extractionStatus === 'ERROR').length;
  const readyToRunCount = pendingCount + errorCount;

  return (
    <div className="min-h-screen bg-slate-100 font-sans text-slate-900 flex flex-col">
      {/* Top Navigation */}
      <header className="bg-indigo-900 text-white shadow-md z-20">
        <div className="container mx-auto px-4 h-16 flex items-center justify-between">
            <div className="flex items-center gap-3">
                <div className="bg-white/10 p-2 rounded-lg">
                    <Stethoscope className="w-6 h-6 text-indigo-300" />
                </div>
                <div>
                    <h1 className="text-xl font-bold tracking-tight">RadExtract <span className="text-indigo-300 font-normal">AI</span></h1>
                    <p className="text-xs text-indigo-200">Radiology Report Variable Extractor</p>
                </div>
            </div>

            {patientData.length > 0 && !isBatchProcessing && (
                <div className="flex gap-4 text-sm">
                    <button 
                        onClick={() => setView('LIST')}
                        className={`flex items-center gap-2 px-3 py-1 rounded transition-colors ${view === 'LIST' ? 'bg-white/20' : 'hover:bg-white/10'}`}
                    >
                        <Database className="w-4 h-4" /> Data Sheet
                    </button>
                     <button 
                        onClick={() => setView('UPLOAD')}
                        className={`flex items-center gap-2 px-3 py-1 rounded transition-colors ${view === 'UPLOAD' ? 'bg-white/20' : 'hover:bg-white/10'}`}
                    >
                        <FileSpreadsheet className="w-4 h-4" /> Import / Add Data
                    </button>
                </div>
            )}
        </div>
      </header>

      {/* Batch Progress Bar */}
      {isBatchProcessing && (
          <div className="bg-indigo-800 text-white px-4 py-2 flex items-center justify-between sticky top-0 z-50 shadow-md">
              <div className="flex items-center gap-3">
                  <Loader2 className="w-4 h-4 animate-spin text-indigo-300" />
                  <span className="text-sm font-medium">Processing Batch... {batchProgress.current} / {batchProgress.total}</span>
              </div>
              <div className="w-64 h-2 bg-indigo-900 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-indigo-300 transition-all duration-300" 
                    style={{ width: `${(batchProgress.current / batchProgress.total) * 100}%` }}
                  />
              </div>
          </div>
      )}

      {/* Main Content */}
      <main className="flex-1 container mx-auto px-4 py-6 overflow-hidden flex flex-col">
        {view === 'UPLOAD' && (
            <div className="max-w-3xl mx-auto mt-6">
                <PatientUploader 
                    onDataLoaded={handleDataLoaded} 
                    existingData={patientData} 
                />
                {patientData.length > 0 && (
                    <div className="text-center mt-6">
                        <button onClick={() => setView('LIST')} className="text-indigo-600 hover:underline">
                            Cancel and return to list
                        </button>
                    </div>
                )}
            </div>
        )}

        {view === 'LIST' && (
            <div className="h-full flex flex-col">
                {/* Batch Action Bar */}
                {readyToRunCount > 0 && (
                    <div className="mb-4 bg-white p-4 rounded-lg border border-indigo-100 flex items-center justify-between shadow-sm">
                        <div className="flex items-center gap-2">
                             <div className={`p-2 rounded-full ${errorCount > 0 ? 'bg-red-50 text-red-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                <FileText className="w-5 h-5" />
                             </div>
                             <div>
                                 <h3 className="font-semibold text-slate-800">Ready to Process</h3>
                                 <p className="text-xs text-slate-500">
                                    {pendingCount} new, {errorCount} failed. Ready for AI analysis.
                                 </p>
                             </div>
                        </div>
                        <button 
                            onClick={handleBatchProcess}
                            disabled={isBatchProcessing}
                            className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${isBatchProcessing ? 'bg-slate-100 text-slate-400' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-md'}`}
                        >
                            {isBatchProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <PlayCircle className="w-4 h-4" />}
                            {isBatchProcessing ? 'Processing...' : (errorCount > 0 ? 'Retry Batch' : 'Run Batch Analysis')}
                        </button>
                    </div>
                )}

                <div className="flex-1 overflow-hidden">
                    <MasterTable 
                        data={patientData} 
                        onSelect={handleSelectPatient} 
                        onExport={handleExport}
                    />
                </div>
            </div>
        )}

        {view === 'DETAIL' && selectedPatientId && (
            <AnalysisView 
                patient={patientData.find(p => p.id === selectedPatientId)!}
                onUpdate={handleUpdatePatient}
                onBack={() => setView('LIST')}
            />
        )}
      </main>
    </div>
  );
};

export default App;

// components/MasterTable.tsx
import React from 'react';
import { MergedRecord } from '../types';
import { Edit2, CheckCircle, Clock, AlertCircle, Download, FileText, XCircle } from 'lucide-react';

interface Props {
  data: MergedRecord[];
  onSelect: (id: string) => void;
  onExport: () => void;
}

export const MasterTable: React.FC<Props> = ({ data, onSelect, onExport }) => {

  const getStatusIcon = (row: MergedRecord) => {
    switch (row.extractionStatus) {
      case 'REVIEWED': return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'EXTRACTED': return <AlertCircle className="w-4 h-4 text-amber-500" />;
      case 'ERROR': return <XCircle className="w-4 h-4 text-red-500" />;
      default: 
        // If text is present but not extracted, show a document icon indicating "Ready"
        if (row.radiologyReportText) {
            return <FileText className="w-4 h-4 text-indigo-500" />;
        }
        return <Clock className="w-4 h-4 text-slate-300" />;
    }
  };

  // Render raw codes 1, 0, 9, 999 for data sheet clarity
  const renderStatus = (val: number | undefined) => {
    if (val === 1) return <span className="bg-green-100 text-green-700 border border-green-200 px-2 py-0.5 rounded text-xs font-mono font-bold">1</span>;
    if (val === 0) return <span className="bg-slate-100 text-slate-500 border border-slate-200 px-2 py-0.5 rounded text-xs font-mono">0</span>;
    if (val === 9) return <span className="text-slate-300 font-mono text-xs">9</span>;
    if (val === 999) return <span className="bg-purple-50 text-purple-600 border border-purple-100 px-1 py-0.5 rounded text-xs font-mono">999</span>;
    return <span className="text-slate-200">-</span>;
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-slate-200 flex flex-col h-full">
      <div className="p-4 border-b border-slate-200 flex justify-between items-center bg-slate-50 rounded-t-lg">
        <div>
            <h2 className="text-lg font-semibold text-slate-800">Patient Data Sheet</h2>
            <p className="text-xs text-slate-500">
                {data.length} records • {data.filter(d => d.extractionStatus === 'REVIEWED').length} completed
            </p>
        </div>
        <button 
            onClick={onExport}
            className="flex items-center gap-2 bg-white border border-slate-300 text-slate-700 px-3 py-1.5 rounded-md text-sm font-medium hover:bg-slate-50 transition-colors"
        >
            <Download className="w-4 h-4" /> Export CSV
        </button>
      </div>

      <div className="overflow-auto flex-1">
        <table className="w-full text-left text-sm text-slate-600">
          <thead className="bg-slate-100 sticky top-0 z-10 text-xs uppercase font-semibold text-slate-500">
            <tr>
              <th className="px-4 py-3 border-b">Status</th>
              <th className="px-4 py-3 border-b">Study ID</th>
              <th className="px-4 py-3 border-b">Patient Name</th>
              <th className="px-4 py-3 border-b">Report File</th>
              <th className="px-4 py-3 border-b">Time to Study</th>
              <th className="px-4 py-3 border-b text-center">Fracture?</th>
              <th className="px-4 py-3 border-b text-center">Vascular?</th>
              <th className="px-4 py-3 border-b text-center">Brain Path?</th>
              <th className="px-4 py-3 border-b text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {data.map((row) => (
              <tr key={row.id} className="hover:bg-indigo-50 transition-colors">
                <td className="px-4 py-3">
                  <div className="flex items-center gap-2 group relative" title={row.extractionError || row.extractionStatus}>
                    {getStatusIcon(row)}
                    {row.extractionStatus === 'ERROR' && row.extractionError && (
                        <div className="hidden group-hover:block absolute left-6 top-0 z-50 bg-slate-800 text-white text-xs p-2 rounded shadow-lg w-48 break-words pointer-events-none">
                            {row.extractionError}
                        </div>
                    )}
                    {row.extractionStatus === 'ERROR' && !row.extractionError && (
                        <span className="text-xs text-red-500">Failed</span>
                    )}
                  </div>
                </td>
                <td className="px-4 py-3 font-medium text-slate-900">{row.id}</td>
                <td className="px-4 py-3">{row.name || '-'}</td>
                <td className="px-4 py-3 text-xs font-mono text-slate-500 truncate max-w-[150px]" title={row.reportFilename}>
                    {row.reportFilename || <span className="text-slate-200 italic">No file</span>}
                </td>
                <td className="px-4 py-3 font-mono text-xs">{row.timeToStudy || '-'}</td>

                {/* Quick stats columns using renamed variables */}
                <td className="px-4 py-3 text-center">
                    {renderStatus(row.extractedData?.fractures)}
                </td>
                <td className="px-4 py-3 text-center">
                    {renderStatus(row.extractedData?.vascular_injury)}
                </td>
                 <td className="px-4 py-3 text-center">
                    {renderStatus(row.extractedData?.brain_pathology)}
                </td>

                <td className="px-4 py-3 text-right">
                  <button
                    onClick={() => onSelect(row.id)}
                    className="text-indigo-600 hover:text-indigo-800 font-medium inline-flex items-center gap-1"
                  >
                    <Edit2 className="w-3 h-3" /> {row.extractionStatus === 'PENDING' || row.extractionStatus === 'ERROR' ? 'Process' : 'Edit'}
                  </button>
                </td>
              </tr>
            ))}
            {data.length === 0 && (
                <tr>
                    <td colSpan={9} className="text-center py-12 text-slate-400">
                        No patients loaded yet. Start by uploading the initial extract.
                    </td>
                </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

// components/AnalysisView.tsx
import React, { useState, useEffect } from 'react';
import { MergedRecord, ExtractedData, AppStatus } from '../types';
import { extractDataFromReport } from '../services/geminiService';
import { Loader2, CheckCircle, AlertCircle, FileText, BrainCircuit, Sparkles } from 'lucide-react';

interface Props {
  patient: MergedRecord;
  onUpdate: (updatedPatient: MergedRecord) => void;
  onBack: () => void;
}

export const AnalysisView: React.FC<Props> = ({ patient, onUpdate, onBack }) => {
  const [reportText, setReportText] = useState(patient.radiologyReportText || '');
  const [data, setData] = useState<ExtractedData | undefined>(patient.extractedData);

  // Initialize status/error based on passed patient record
  const [status, setStatus] = useState<AppStatus>(
      patient.extractionStatus === 'ERROR' ? AppStatus.ERROR : 
      patient.extractionStatus === 'REVIEWED' ? AppStatus.SUCCESS : AppStatus.IDLE
  );
  const [errorMsg, setErrorMsg] = useState(patient.extractionError || '');

  // Allow passing specific text (e.g., from paste event) or use current state
  const handleExtract = async (textOverride?: string) => {
    const textToProcess = textOverride ?? reportText;

    if (!textToProcess || !textToProcess.trim()) {
        setErrorMsg("Please enter report text first.");
        return;
    }

    setStatus(AppStatus.LOADING);
    setErrorMsg('');

    try {
      const result = await extractDataFromReport(textToProcess);
      setData(result);
      setStatus(AppStatus.SUCCESS);

      // Save results
      onUpdate({
        ...patient,
        radiologyReportText: textToProcess,
        extractedData: result,
        extractionStatus: 'REVIEWED',
        extractionError: undefined // Clear previous errors
      });
    } catch (err: any) {
      console.error(err);
      setStatus(AppStatus.ERROR);

      // Robust error message extraction
      let msg = "Failed to extract data. Check API key and try again.";
      if (err instanceof Error) {
        msg = err.message;
      } else if (typeof err === 'string') {
        msg = err;
      } else if (err && typeof err === 'object') {
        // Try to stringify if it's an object (like a raw API response error)
        try {
            msg = JSON.stringify(err);
            if (msg === '{}') msg = "Unknown error occurred (empty object).";
        } catch (e) {
            msg = "Unknown error occurred.";
        }
      }

      setErrorMsg(msg);
      // We don't necessarily update the parent record here unless we want to persist the 'ERROR' status
      // For now, let's persist it so it shows in the list if they go back
      onUpdate({
          ...patient,
          extractionStatus: 'ERROR',
          extractionError: msg
      });
    }
  };

  const handlePaste = (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    const pastedText = e.clipboardData.getData('text');
    // If the text area is mostly empty and we paste a significant amount of text,
    // we assume it's a new report and trigger extraction automatically.
    if (reportText.trim().length < 50 && pastedText.length > 50) {
        // Trigger extraction with the pasted text
        handleExtract(pastedText);
    }
  };

  const handleFieldChange = (key: keyof ExtractedData, value: any) => {
    if (!data) return;
    const newData = { ...data, [key]: value };
    setData(newData);
    onUpdate({
      ...patient,
      radiologyReportText: reportText,
      extractedData: newData,
      extractionStatus: 'REVIEWED',
      extractionError: undefined
    });
  };

  return (
    <div className="flex flex-col h-[calc(100vh-100px)]">
      {/* Header */}
      <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-200">
        <div>
          <button onClick={onBack} className="text-sm text-slate-500 hover:text-indigo-600 mb-1">
            ← Back to List
